async function checkLink(value,fetcher=fetch){
 let url=publicURL(value);const original=url.href,redirects=[],validatedHosts=new Set();
 for(let hop=0;hop<6;hop++){
  if(!validatedHosts.has(url.hostname)){await checkDNS(url.hostname,fetcher);validatedHosts.add(url.hostname)}
  if(/\/(logout|signout|delete|remove|unsubscribe|checkout)(\/|$)/i.test(url.pathname))return {url:original,state:'unverified',result:'Action link skipped',explanation:'This link may perform an account or checkout action.',nextStep:'Check this action manually in your browser.',redirects};
  let r,method='HEAD';try{r=await fetcher(url.href,{method:'HEAD',redirect:'manual',signal:AbortSignal.timeout(10000)});if([401,403,404,405,410,429,501].includes(r.status)){await r.body?.cancel();method='GET';r=await fetcher(url.href,{method:'GET',headers:{Accept:'text/html','User-Agent':'WebsiteQC/2.0 (page quality review)'},redirect:'manual',signal:AbortSignal.timeout(10000)})}}catch{return{url:original,state:'unverified',result:'Connection failed',explanation:'The scanner could not get a response before the connection failed or timed out.',nextStep:'Open the link manually to check whether it loads for you.',redirects}}
  let status=r.status;let location=r.headers.get('Location');await r.body?.cancel();
  // A missing-page verdict must come from normal GET responses, never HEAD alone.
  if(method==='GET'&&[404,410].includes(status)){
   const firstStatus=status;
   try{const confirmation=await fetcher(url.href,{method:'GET',headers:{Accept:'text/html','User-Agent':'WebsiteQC/2.0 (page quality review)','Cache-Control':'no-cache'},redirect:'manual',signal:AbortSignal.timeout(10000)});status=confirmation.status;location=confirmation.headers.get('Location');await confirmation.body?.cancel();if(status!==firstStatus&&[404,410].includes(status))return {url:original,finalUrl:url.href,status,method,redirects,state:'unverified',result:'Inconsistent missing-page responses',explanation:'The destination returned different responses on repeat checks.',nextStep:'Open this destination manually before changing the link.'}}
   catch{return {url:original,finalUrl:url.href,status:firstStatus,method,redirects,state:'unverified',result:'Missing-page response not confirmed',explanation:'One GET reported a missing page, but the confirmation request failed.',nextStep:'Open the destination manually before changing this link.'}}
  }
  if([301,302,303,307,308].includes(status)&&location){url=publicURL(new URL(location,url).href);redirects.push(url.href);continue}
  const labels={401:'Sign-in required (401)',403:'Scanner denied access (403)',404:'Page not found (404)',410:'Page removed (410)',429:'Too many checks (429)'};
  const explanations={401:'The destination requires authentication.',403:'The server refused the automated check. This does not establish whether the link works for a normal visitor.',404:'Two normal GET requests returned HTTP 404. Some sites also return this to automated clients; check the destination manually before replacing it.',410:'Two normal GET requests returned HTTP 410. Confirm manually before replacing this destination.',429:'The server is temporarily limiting automated requests.'};
  const verified=status>=200&&status<300,broken=[404,410].includes(status);
  return {url:original,finalUrl:url.href,status,method,redirects,state:broken?'broken':verified?'verified':'unverified',result:labels[status]||(verified?(redirects.length?'Loads after redirect':'Loads successfully'):'Server returned HTTP '+status),explanation:explanations[status]||(verified?'The destination returned a successful HTTP response.':status>=500?'The destination server reported an error. Its availability may be temporary.':'The destination could not be verified.'),nextStep:broken?'Open this exact URL in your browser. Replace it only if it also fails there.':verified?'':status===429?'Wait a few minutes, then check again.':'Open this link manually. If it loads, ask the developer to check why automated requests are refused.'};

 }
 return {url:original,state:'unverified',result:'Redirect loop or long chain',explanation:'The destination redirected more than five times.',nextStep:'Open the link manually and have the developer simplify its redirects.',redirects};
}

async function discoverSite(root,fetcher=fetch,validate=async()=>{}){
 const origin=new URL(root).origin,queue=[origin+'/sitemap.xml'],seen=new Set(),urls=new Set(),warnings=[];
 const same=value=>{const u=new URL(value,origin);if(u.hostname.replace(/^www\./,'')!==new URL(origin).hostname.replace(/^www\./,'')||!['https:','http:'].includes(u.protocol))throw Error('Off-site sitemap excluded');return u};
 while(queue.length&&seen.size<12){let target=queue.shift();if(seen.has(target))continue;seen.add(target);try{let response;for(let hop=0;hop<5;hop++){const u=same(target);await validate(u.hostname);response=await fetcher(u.href,{redirect:'manual',signal:AbortSignal.timeout(15000)});if([301,302,303,307,308].includes(response.status)){target=same(new URL(response.headers.get('location'),u).href).href;continue}break}if(!response.ok)throw Error('HTTP '+response.status);if(Number(response.headers.get('content-length'))>1000000)throw Error('Sitemap too large');const reader=response.body.getReader();let raw='',size=0;const decoder=new TextDecoder();for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>1000000){await reader.cancel();throw Error('Sitemap too large')}raw+=decoder.decode(value,{stream:true})}raw+=decoder.decode();const locs=[...raw.matchAll(/<loc\b[^>]*>([\s\S]*?)<\/loc>/gi)].map(m=>m[1].trim().replace(/&amp;/g,'&').replace(/^<!\[CDATA\[|\]\]>$/g,''));for(const loc of locs){try{const u=same(loc);if(/<sitemapindex\b/i.test(raw))queue.push(u.href);else urls.add(u.href)}catch{}if(urls.size>=2000)break}if(urls.size>=2000){warnings.push('Sitemap discovery reached 2,000 URLs; linked-page discovery continues.');break}}catch(error){warnings.push(target+': '+error.message)}}
 if(queue.length)warnings.push('Some sitemap files were not read; linked-page discovery continues.');return {urls:[...urls],warnings};
}

